extern EngineContext g_defaultContext;
extern EngineContext * g_currentContext;

inline EngineContext & context() { return *g_currentContext; }

// Makes `ctx` the current context for the lifetime of the object.
class ScopedContext
{
public:
	explicit ScopedContext(EngineContext & ctx) : m_previous(g_currentContext) { g_currentContext = &ctx; }
	~ScopedContext() { g_currentContext = m_previous; }
	ScopedContext(const ScopedContext &) = delete;
	ScopedContext & operator=(const ScopedContext &) = delete;
private:
	EngineContext * m_previous;
};

